def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opps = 0
    rich_opps = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY:
                rich_opps += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opps += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev['bid']))
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 17.0
    loose_supply = supply >= 22.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if tight_supply:
        danger += 1

    if day >= 8:
        danger += 1

    if highest_prev >= 100:
        market = 'crazy'
    elif highest_prev >= 70:
        market = 'hot'
    elif highest_prev >= 35:
        market = 'warm'
    else:
        market = 'cool'

    if danger >= 5:
        bid = max(95.0, highest_prev + 3.0)
    elif danger >= 3:
        if market == 'crazy':
            bid = 88.0
        elif market == 'hot':
            bid = max(72.0, avg_prev * 0.92)
        elif market == 'warm':
            bid = max(46.0, highest_prev + 2.0)
        else:
            bid = 42.0
    else:
        if loose_supply and urgent_opps == 0:
            bid = 16.0
        elif market == 'crazy':
            bid = 12.0 if hp > 4 else 76.0
        elif market == 'hot':
            bid = 22.0 if hp > 5 else 58.0
        elif market == 'warm':
            bid = max(24.0, min(40.0, avg_prev * 0.75))
        else:
            bid = 28.0 if tight_supply else 20.0

    if rich_opps >= 2 and hp <= 4:
        bid = max(bid, highest_prev + 2.5 if highest_prev > 0 else 65.0)

    if budget < bid:
        bid = budget

    min_live_bid = 0.0
    if hp <= 2 or no_water_days >= 2:
        min_live_bid = min(budget, 35.0)
    elif hp <= 4 or no_water_days >= 1:
        min_live_bid = min(budget, 22.0)

    if bid < min_live_bid:
        bid = min_live_bid

    if bid < 0:
        bid = 0.0

    return float(round(min(bid, budget), 2))
